    dY(70) = LambdaX*Y(65) + Y(69)*thetas - Y(70)*(gamma3s + gammaY + mu + nuY + sigmaX) + Y(30)*epsY*sigmaY;
    dY(71) = Y(75)*gamma3s - Y(71)*(Lambdas + gammaY + mu + nuX + nuY) + Y(31)*epsY*sigmaY - Y(66)*sigmaX*(epsX - 1);
    dY(72) = Lambdas*Y(71) - Y(72)*(gammaY + mu + nuX + nuY + sigmas) + Y(32)*epsY*sigmaY - Y(67)*sigmaX*(epsX - 1);
    dY(73) = Y(72)*sigmas - Y(73)*(gammaY + mu + nuX + nuY + taus) + Y(33)*epsY*sigmaY - Y(68)*sigmaX*(epsX - 1);
    dY(74) = Y(73)*taus - Y(74)*(gammaY + mu + nuX + nuY + thetas) + Y(34)*epsY*sigmaY - Y(69)*sigmaX*(epsX - 1);
    dY(75) = Y(74)*thetas - Y(75)*(gamma3s + gammaY + mu + nuX + nuY) + Y(35)*epsY*sigmaY - Y(70)*sigmaX*(epsX - 1);
    dY(76) = Y(80)*gamma3s - Y(76)*(Lambdas + gammaX + gammaY + mu + nuX + nuY) + Y(36)*epsY*sigmaY + Y(66)*epsX*sigmaX;
    dY(77) = Lambdas*Y(76) - Y(77)*(gammaX + gammaY + mu + nuX + nuY + sigmas) + Y(37)*epsY*sigmaY + Y(67)*epsX*sigmaX;
    dY(78) = Y(77)*sigmas - Y(78)*(gammaX + gammaY + mu + nuX + nuY + taus) + Y(38)*epsY*sigmaY + Y(68)*epsX*sigmaX;
    dY(79) = Y(78)*taus - Y(79)*(gammaX + gammaY + mu + nuX + nuY + thetas) + Y(39)*epsY*sigmaY + Y(69)*epsX*sigmaX;
    dY(80) = Y(79)*thetas - Y(80)*(gamma3s + gammaX + gammaY + mu + nuX + nuY) + Y(40)*epsY*sigmaY + Y(70)*epsX*sigmaX;
    
